89	const RUN_LOG_DEFAULT_LIMIT_BYTES = 256_000;
90	const RUN_LOG_MAX_LIMIT_BYTES = 1024 * 1024;
91	
92	function readRunLogLimitBytes(value: unknown) {
93	  const parsed = Number(value ?? RUN_LOG_DEFAULT_LIMIT_BYTES);
94	  if (!Number.isFinite(parsed)) return RUN_LOG_DEFAULT_LIMIT_BYTES;
95	  return Math.max(1, Math.min(RUN_LOG_MAX_LIMIT_BYTES, Math.trunc(parsed)));
96	}
