98	function readLiveRunsQueryInt(value: unknown, max: number, fallback = 0) {
99	  const parsed = Number(value);
100	  if (!Number.isFinite(parsed)) return fallback;
101	  return Math.max(0, Math.min(max, Math.trunc(parsed)));
102	}
